SELECT  FROM inserted

SELECT 
FROM session_events
WHERE workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND external_id = #{eventExternalID}
AND deleted_at IS NULL

SELECT payload->>'_echo_key'
FROM session_events
WHERE workspace_uuid = #{workspaceUUID}
  AND session_external_id = #{sessionExternalID}
  AND payload->>'model_request_start_id' = #{requestID}
  AND payload->>'_echo_source' = #{source}
  AND payload->>'_echo_key' IS NOT NULL
  AND deleted_at IS NULL

SELECT EXISTS (
    SELECT 1 FROM session_events
    WHERE workspace_uuid = #{workspaceUUID} AND session_external_id = #{sessionExternalID}
      AND external_id = #{eventExternalID}
)

SELECT 
FROM session_events

    workspace_uuid = #{params.WorkspaceUUID}
    AND session_external_id = #{params.SessionExternalID}
    AND deleted_at IS NULL
    AND seq IS NOT NULL

        AND thread_external_id = #{params.ThreadExternalID}


        AND thread_external_id = (
            SELECT external_id FROM session_threads
            WHERE workspace_uuid = #{params.WorkspaceUUID}
            AND session_external_id = #{params.SessionExternalID}
            AND parent_thread_uuid IS NULL
            AND deleted_at IS NULL
            ORDER BY created_at ASC, uuid ASC
            LIMIT 1
        )


        AND event_type IN
        #{eventType}

    AND processed_at > #{params.CreatedAtGT}
    AND processed_at >= #{params.CreatedAtGTE}
    AND processed_at < #{params.CreatedAtLT}
    AND processed_at <= #{params.CreatedAtLTE}
    AND COALESCE(seq, queued_after_seq) > #{params.AfterSeq}
    AND COALESCE(seq, queued_after_seq) <= #{params.ThroughSeq}

        AND (COALESCE(seq, queued_after_seq), seq IS NULL, id)
        <>
        (
            SELECT COALESCE(queued_after_seq, seq - 1), trueCOALESCE(seq, queued_after_seq), seq IS NULL, id
            FROM session_events
            WHERE workspace_uuid = #{params.WorkspaceUUID}
            AND session_external_id = #{params.SessionExternalID}
            AND external_id = #{params.Cursor.ExternalID}
        )


ORDER BY COALESCE(seq, queued_after_seq) , (seq IS NULL) , id 
LIMIT #{params.FetchLimit}

