SELECT

FROM session_events
WHERE organization_uuid = #{organizationUUID}
  AND workspace_uuid = #{workspaceUUID}
  AND session_uuid = #{sessionUUID}
  AND deleted_at IS NULL
ORDER BY created_at ASC, id ASC

SELECT EXISTS (SELECT 1 FROM session_events
WHERE workspace_uuid = #{workspaceUUID} AND session_external_id = #{sessionExternalID}
AND thread_external_id = #{threadID} AND event_type = 'user.message'
AND processed_at IS NULL AND deleted_at IS NULL)
AND NOT EXISTS (
    SELECT 1 FROM session_events interrupted
    WHERE interrupted.workspace_uuid = #{workspaceUUID}
      AND interrupted.session_external_id = #{sessionExternalID}
      AND interrupted.thread_external_id = #{threadID}
      AND interrupted.event_type = 'user.interrupt'
      AND interrupted.processed_at IS NOT NULL
      AND interrupted.processed_at <= #{at}
      AND interrupted.deleted_at IS NULL
      AND interrupted.processed_at >= (
          SELECT started.processed_at FROM session_events started
          WHERE started.workspace_uuid = #{workspaceUUID}
            AND started.session_external_id = #{sessionExternalID}
            AND started.event_type IN ('session.thread_status_running', 'session.thread_status_rescheduled')
            AND started.payload->>'session_thread_id' = #{threadID}
            AND started.deleted_at IS NULL
          ORDER BY started.id DESC LIMIT 1
      )
) AS blocks_idle

SELECT COUNT(*) > 0 FROM session_events
 WHERE organization_uuid = #{organizationUUID} AND workspace_uuid = #{workspaceUUID}
 AND session_external_id = #{sessionExternalID} AND event_type = 'user.tool_confirmation'
 AND processed_at IS NULL AND deleted_at IS NULL AND tool_use_id IN
 #{id}
